async function run(name,fn,options={}){const row={name,engine,errors:[],checks:[]};const ctx=await browser.newContext({viewport:{width:390,height:844},isMobile:true,hasTouch:true,reducedMotion:'reduce',serviceWorkers:'block',...options});const page=await ctx.newPage();page.setDefaultTimeout(30000);page.on('pageerror',e=>row.errors.push(e.message));
async function shot(label){const options={path:`${out}/${engine}-${name}-${label}.jpg`,type:'jpeg',quality:86,timeout:45000};try{await page.screenshot(options);}catch(error){if(!String(error).includes('Timeout'))throw error;row.checks.push({captureRetry:label});await page.screenshot({...options,timeout:60000});}}
async function audit(label){await page.evaluate(axe);const violations=await page.evaluate(async()=>{const r=await axe.run(document,{runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21aa','wcag22aa']}});return r.violations.map(v=>({id:v.id,impact:v.impact,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary}))}));});row.checks.push({axe:label,violations});assert.deepEqual(violations,[],label+' accessibility violations');}
async function reflow(){await page.waitForFunction(()=>document.documentElement.scrollWidth<=innerWidth+1,null,{timeout:3000}).catch(()=>{});const geometry=await page.evaluate(()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,textOverflow:(()=>{const out=[],walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while((n=walker.nextNode())){if(!n.textContent.trim()||n.parentElement.closest('script,style,option'))continue;const r=document.createRange();r.selectNodeContents(n);const b=r.getBoundingClientRect();if(b.right>innerWidth+1)out.push({parent:n.parentElement.tagName,cls:n.parentElement.className,text:n.textContent.slice(0,60),right:b.right});if(out.length>=10)break;}return out;})(),internal:Array.from(document.querySelectorAll('body *')).filter(e=>e.scrollWidth>e.clientWidth+2&&e.clientWidth>0).slice(0,10).map(e=>({tag:e.tagName,cls:e.className,width:e.clientWidth,scroll:e.scrollWidth})),offenders:Array.from(document.querySelectorAll('body *')).filter(e=>e.getBoundingClientRect().right>innerWidth+1).slice(0,12).map(e=>({tag:e.tagName,cls:e.className,text:e.textContent.slice(0,70),right:e.getBoundingClientRect().right,width:e.getBoundingClientRect().width}))}));assert(geometry.scroll<=geometry.width+1,'Horizontal overflow '+JSON.stringify(geometry));}
try{await fn({page,ctx,row,shot,audit,reflow});assert.deepEqual(row.errors,[]);row.pass=true;}catch(e){row.pass=false;row.failure=e.stack;await shot('failure').catch(()=>{});}results.push(row);fs.writeFileSync(`${out}/${engine}-results.json`,JSON.stringify(results,null,2));console.log('EASY_CASE '+JSON.stringify(row));await ctx.close();}
